package io.github.caoy123456.shortlink.repository;

import io.github.caoy123456.shortlink.domain.ShortUrl;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import java.util.Optional;

/**
 * All SQL for the {@code short_url} table lives here.
 *
 * <p>This is deliberately hand written rather than generated by MyBatis-Plus
 * or Spring Data. Every statement below is one you can read, explain, and
 * reason about the cost of - which is the entire point of the exercise.
 *
 * <p>{@link JdbcClient} is Spring's modern fluent wrapper over JDBC (added in
 * Spring 6.1). It handles connections, statement lifecycle and mapping; it
 * does not write SQL for you.
 */
@Repository
public class ShortUrlRepository {

    private final JdbcClient jdbcClient;

    // Constructor injection, not @Autowired on a field: it makes the
    // dependency explicit and lets the field be final.
    public ShortUrlRepository(JdbcClient jdbcClient) {
        this.jdbcClient = jdbcClient;
    }

    /**
     * Inserts the long URL and returns the generated auto-increment id.
     *
     * <p>The id is what we encode into a short code, so we must get it back
     * from the database. That is what the {@link KeyHolder} is for: it
     * captures keys MySQL generated during the insert.
     *
     * @return the new row's id
     */
    public long insertLongUrl(String longUrl) {
        KeyHolder keyHolder = new GeneratedKeyHolder();

        jdbcClient.sql("insert into short_url (long_url) values (:longUrl)")
                .param("longUrl", longUrl)
                .update(keyHolder);

        Number key = keyHolder.getKey();
        if (key == null) {
            // Should be unreachable: the column is auto-increment. If it does
            // happen, failing loudly beats returning a wrong id.
            throw new IllegalStateException("database did not return a generated id");
        }
        return key.longValue();
    }

    /**
     * Writes the computed short code back onto the row we just inserted.
     */
    public void updateShortCode(long id, String shortCode) {
        int rows = jdbcClient.sql("update short_url set short_code = :shortCode where id = :id")
                .param("shortCode", shortCode)
                .param("id", id)
                .update();

        if (rows != 1) {
            throw new IllegalStateException(
                    "expected to update exactly 1 row for id " + id + ", updated " + rows);
        }
    }

    /**
     * Looks up a row by its short code.
     *
     * <p>This is the hot path: it runs on every single redirect. It is fast
     * because {@code short_code} carries a unique index - without that index
     * MySQL would scan the whole table on every click.
     *
     * <p>Returns {@link Optional} rather than null so the caller is forced to
     * handle "no such code" instead of accidentally dereferencing null.
     */
    public Optional<ShortUrl> findByShortCode(String shortCode) {
        return jdbcClient.sql("""
                        select id, short_code, long_url, click_count, created_at
                        from short_url
                        where short_code = :shortCode
                        """)
                .param("shortCode", shortCode)
                .query(ShortUrl.class)
                .optional();
    }

    /**
     * Increments the click counter for a code.
     *
     * <p>Note the counter is incremented <em>in the database</em>
     * ({@code click_count = click_count + 1}) rather than read into Java,
     * incremented, and written back. The second approach loses counts when two
     * requests overlap; this one cannot, because the database serialises the
     * update.
     *
     * <p>This still costs one write per redirect, which is why M2 moves the
     * counter into Redis.
     */
    public void incrementClickCount(String shortCode) {
        jdbcClient.sql("update short_url set click_count = click_count + 1 where short_code = :shortCode")
                .param("shortCode", shortCode)
                .update();
    }
}
